from math import comb

def odd_df(k):
    if k <= 0: return 1
    r = 1
    for i in range(k):
        r *= (2*i + 1)
    return r

def g_d(d):
    return {k: comb(d, 2*k) * odd_df(k) for k in range(d//2 + 1)}

def multiply(p1, p2, md):
    r = {}
    for e1, c1 in p1.items():
        for e2, c2 in p2.items():
            e = e1 + e2
            if e <= md:
                r[e] = r.get(e, 0) + c1 * c2
    return r

# N=44 tree degrees
degrees = [8,7,6,5,4,4,3,3] + [2]*10 + [1]*26

result = {0: 1}
for d in degrees:
    result = multiply(result, g_d(d), 21)

coeff = result.get(21, 0)
print(f'Coefficient of x^21: {coeff}')
print(f'Modulo 997: {coeff % 997}')

# Verify anchors
print()
anchors = [
    ([1,2,1], 2, 0, 1),      # P3 K=2
    ([1,2,2,1], 2, 1, 2),    # P4 K=2
    ([1,2,2,2,1], 2, 2, 3),  # P5 K=2
    ([3,1,1,1], 2, 1, 3),    # S3 K=2
    ([4,1,1,1,1], 2, 2, 3),  # S4 K=2
]
for degs, K, target, expected in anchors:
    E = len(degs) - 1
    r = {0: 1}
    for d in degs:
        r = multiply(r, g_d(d), E - K)
    actual = r.get(E - K, 0)
    print(f'{degs} K={K}: expected {expected}, got {actual}, match={actual == expected}')
"

